interface Animal {
    readonly void speak();
}

class Dog implements Animal {
    public readonly void speak() { println("Ouaf !"); }
}

class Cat implements Animal {
    public readonly void speak() { println("Miaou !"); }
}

void speakTwice(borrow Animal animal) {
    animal.speak();
    animal.speak();
}

void main() {
    Animal animal = new Dog();
    speakTwice(animal);
    // Le remplacement detruit le Dog, puis conserve le Cat.
    animal = new Cat();
    animal.speak();
}

interface CounterAccess {
    void increment();
    readonly int getValue();
}

class Counter implements CounterAccess {
    private int value;
    Counter(int value) { this.value = value; }
    public void increment() { this.value = this.value + 1; }
    public readonly int getValue() { return this.value; }
}

void bump(borrow mut CounterAccess counter) { counter.increment(); }

void main() {
    Counter counter = new Counter(40);
    bump(counter); // Emprunt et conversion d'interface implicites, sans allocation.
    {
        borrow CounterAccess reader = counter;
        println(reader.getValue());
        // counter.increment() serait refuse pendant cet emprunt.
    }
    counter.increment();
    println(counter.getValue());
}

// Les methodes du modele sont verifiees pour chaque specialisation demandee.
class Box<T> {
    private T value;
    public Box(T value) { this.value = value; }
    public readonly T get() { return this.value; }
}

void main() {
    Box<int> number = new Box<int>(42);
    Box<String> text = new Box<String>("Bonjour les generiques !");
    Box<boolean> flag = new Box<boolean>(true);
    println(number.get());
    println(text.get());
    println(flag.get());
}

class Counter {
    private int value;
    Counter(int value) { this.value = value; }
    readonly int getValue() { return this.value; }
}

class Holder<T> {
    private T content;
    Holder(T content) { this.content = content; }
    readonly int read() { return this.content.getValue(); }
}

void main() {
    Counter counter = new Counter(42);
    Holder<Counter> holder = new Holder<Counter>(counter);
    // counter a ete transfere dans holder.
    println(holder.read());
    // La destruction de holder detruit aussi son Counter.
}

interface Source<T> {
    readonly T read();
}

class Constant<T> implements Source<T> {
    private T value;
    Constant(T value) { this.value = value; }
    public readonly T read() { return this.value; }
}

void main() {
    Source<int> number = new Constant<int>(42);
    Source<String> text = new Constant<String>("Polymorphisme generique");
    println(number.read());
    println(text.read());
}

interface Readable { readonly int read(); }

class Number implements Readable {
    private int value;
    Number(int value) { this.value = value; }
    readonly int read() { return this.value; }
}

class ReadJob {
    private Readable source;
    ReadJob(Readable source) { this.source = source; }
    readonly int execute() { return this.source.read(); }
}

Readable make(boolean first) {
    if (first) { return new Number(42); }
    else { return new Number(7); }
}

void main() {
    ReadJob task = new ReadJob(make(true));
    println(task.execute());
    Readable other = make(false);
    println(other.read());
}

